(window.webpackJsonp=window.webpackJsonp||[]).push([[94],{536:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、我们在读福音书的时候，不要看耶稣做了什么事了，就想当然认为他是神，当然可以做；而是要思考：他作为人，是如何做的？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、我们遇到的一切事情，都最终是神所安排的。而神就是这样把我们带入到一个又一个由魔鬼或者人所造成的“试探”当中来“试炼”我们。我们不能说是神试探我们，因为神并不乐于见到我们在试探中失败。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、福音书记载的耶稣所受的三个试探，代表着人类的三种需要：物质肉身产生的需要、生命目产生的需要，以及出于位格关系产生的需要。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、试探的构成要素：（1）被试探的人确实有这个需求，或者说想要某个东西，并且（2）他也确实有可能来做某个行为，并且（3）他做了之后，是可能确实会成功地获得这个东西的")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、试探的本质：挑动人的私欲。他首先把你的需求展示给你，然后把脱离了神来满足这个需求的手段告诉你，并且让你看到用这个手段确实有可能实现需求，这样来引动你的私欲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。好，今天我们进入到路加福音的第4章。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在开始之前，我想先谈一个重要的问题，就是“耶稣是谁”？大家不要觉得奇怪。我知道这是我们上次讲道的题目。但如果你还记得，我们上次从最开始就跟大家说，我们不会从信条或者系统神学的教义来讲耶稣是谁，而是从第3章的经文出发。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但今天在这里，我有必要直接把关于基督论的教义告诉你们，这样我们在读福音书和理解接下来的经文，才能对耶稣所做的有正确的理解和把握。这些教义不是从某一段经文归纳出来的，而是从很多经文，经过历世历代的神学家们讨论、总结出来的：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣基督是完全的神，也是完全的人。他只有一个位格，就是圣子这个位格（所谓“位格”，可以粗浅理解成是一种有情感、理性、意志的生命的身份），这是一个神的位格。在这个位格上有两个本性，一是神性，一是人性。他的神性和圣父、圣灵的神性是同一的。他在永恒中本来只有一个位格（就是圣子），一个本性（就是神性），但在公元前5年左右，他进入到时间当中，在神性上添加了人性；在世期间，他是抑制了自己的神性，作为人活在这个世界上。这就是道成肉身。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们要注意，耶稣在世上做的事，是圣子这个神的位格在他的人性中做的；他所表现出的生命状态，是他作为一个完全的人而有的生命状态。正因为此，耶稣自己对门徒说“我所做的事，信我的人也要做”（约翰福音14:12）；也正因为此，保罗告诉我们要“效法基督耶稣”，因为我们作为人，也可以活出他作为完全的人的生命状态来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个观念一定要印到我们脑袋中。我们在读福音书的时候，不要看耶稣做了什么事了，就想当然认为：他是神，当然可以做；而是要思考：他作为人，是如何做的？尤其在今天的经文中，我们一定要知道，他是在人性中来受试探的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好我们进入到经文当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("虽然我们上次讲道提到，从后面来看，我们知道耶稣这个神的儿子成功地完成了他的使命、一生都顺服神。但如果我们单看路加福音，一直要到第23:46节，（那里记载了耶稣在十字架上死前的最后一刻的情况。当时耶稣大声喊着说：“父啊，我将我的灵魂交在你手里！”说了这话，气就断了），我们才能知道耶稣是不是成功了。在此之前，这个儿子最终能否成功，其实都是不确定的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在路加福音第3章结尾，路加提到“亚当是神的儿子”，让我们想起那个失败的亚当，他在伊甸园中被魔鬼试探，败下阵来。进入到第4章，神的另一个儿子也将面临魔鬼的试探，这一次他的表现会怎么样呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、认识试探的来源")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们首先来看第4章的第1节，这里说耶稣受了洗回来，“被圣灵充满”。“被圣灵充满”就是指耶稣完全处于被圣灵掌控的状态。注意这种状态不是说他失去自我意识了，像我们看到的一些电影里讲的鬼上身一样，自己都不知道自己在干什么了。不是这样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这说起来有点神秘。一个被圣灵充满的人，就是圣灵用神的意思来引导他的本性，而他自己的本性则生发出要回应这种引导的理性、情感，最终他自己在意志上进行选择，做出回应、顺服这种引导的决定，并在行动上实际去执行这个决定。所以在他自己看来，他是在自己选择顺服神的带领；而在神看来，实际上是神在使他做出这个选择。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当耶稣从约旦河回来，神对他的带领是什么呢？第4章1节接着说，圣灵将他引到旷野，四十天受魔鬼的试探。第2节说 ，那些日子没有吃什么，日子满了，他就饿了。这两节经文里告诉了我们，他这四十天是持续受魔鬼试探，而不仅仅是四十天之后才开始受试探。只不过，只有四十天以后所受的这三个试探，被耶稣告诉他的门徒，然后被记录下来了而已。为什么会特别记录者三个？我们之后会来讲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在这四十天里面，他处于禁食的状态，第2节说，当日子满了，他就饿了。马太福音4:2也说，“他禁食四十昼夜，后来就饿了。”从这些表述当中我们可以推测，大概的情况是：在这四十天的禁食生活中，由于神的保守，耶稣并不是像我们一样，一天不吃饭就饿得不行。在神的保守下，他这四十天虽然在禁食，但身体的能量所需仍然是够的（这种情况并不是第一次发生，在列王纪上19章就记载，先知以利亚曾经吃一顿饭，神保守他仗着这一顿饭就一直走了四十个昼夜）。但到了第四十天，日子满了，神就撤回了对他身体能量的这种供应，于是他在此之后，他就饿了。这当然就给了魔鬼可乘之机，开始了第3节所记载的试探。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们可以看到，正是他被圣灵充满，意志上完全顺服神的带领，而神带领他进入试探当中，他才会受到试探；而四十天之后，也正是神撤回了对他的能量供应，因此他变得饥饿，才给了魔鬼可乘之机。所以耶稣遭遇这些试探，最终来说，是神的安排。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那我们可不可以说是神在试探耶稣呢？不可以。雅各书1:13节说得很清楚，神不试探人。所以虽然是神安排耶稣进入到试探当中，但实施试探的是魔鬼，而不是神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这有什么区别？这里面的重大区别，就在心态的问题。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("魔鬼对耶稣所做的事，他是希望、享受于见到他犯罪，因此心是恶的。而神对耶稣所做的事，神并不希望，更不乐于见到他犯罪，因此神的心是善的。至于神这样做，他的心是喜悦于什么样的结果？路加这里没有明确指出来，但我们可以根据发生的结果，来看到神使耶稣进入试探当中，他喜悦于什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们刚才已经读了，耶稣在这个受试探的过程中，是使用神的话来抵挡魔鬼，因此当他经历了试探，他一定是对神的话语更有信心，所以这一定是神喜悦看到的事情之一；马太福音记载，在他经历了试探之后，魔鬼离开他，“有天使来伺候他”，因此让他亲身经历胜过试探后的喜悦并获得神的奖赏，这也一定是神喜悦的事情；他经历这场试探，因此福音书的作者可以记录下来，让神的百姓知道我们也可以像耶稣一样胜过试探，这一定也是神喜悦的事情。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神让一件事情发生，可能有多重目的，但无论有多少，只有一种目的是不可能的：就是他要享受人犯罪、他要从人犯罪当中获得愉悦。为了让良善的事，也就是他喜悦的事成就，他可能会使用魔鬼的恶心，但他自己的心是良善的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("就像在约伯记中，魔鬼想要引起约伯犯罪，以证明神的百姓敬畏他只不过是因为神给了他们好处，以此来嘲笑神。魔鬼的心是恶的。在神的允许下，他去毁坏约伯的财产、仆人、儿女，甚至约伯的身体，以期让约伯不再敬畏神。他这就是在试探约伯。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而神允许魔鬼去对约伯做这些事，并不是因为他喜悦、享受看到约伯犯罪，然后喜欢看到约伯因为犯罪而受惩罚；如果是那样，神就成了变态，他就不是神，而是魔鬼。神允许魔鬼去试探约伯，因为神喜悦看到约伯在经历这场苦难之后，对神的信心更加坚固（约伯记42:1~6）；喜悦看到约伯享受胜过试探之后神的奖赏（约伯记42:10~16）；也喜悦看到约伯的故事被记载下来，安慰、鼓励无数在经历苦难中的神的儿女。感谢约伯，也感谢主，神所喜悦看到的事情都实现了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，我们要清楚地认识到，是神让耶稣进入到旷野当中40天受魔鬼的试探；是神让耶稣饿了，因此魔鬼可以用饮食的问题试探他；是神允许，因此魔鬼可以使用示巴人、从天而降的火、迦勒底人、狂风、细菌来试探约伯。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，是神允许，因此魔鬼可以使用国安、警察来给某个弟兄处分；是神允许，因此魔鬼可以使用某个在读书的弟兄的老师、学院领导来胁迫或者利诱你们；是神允许，因此魔鬼可以使某个弟兄在上网的时候，突然访问到一个黄色网站；是神允许，因此魔鬼可以使用学业、工作、婚姻、买房、孩子、父母等等各种世上的事来使我们担忧、思虑。甚至，也是神允许，因此魔鬼可以使用神已经给与我们的学位、工作、婚姻、房子、金钱、孩子、父母、朋友来使我们躺平、享受肉体和眼目的情欲被满足而有的岁月静好、温情脉脉。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("换句话说，我们遇到的一切事情，都最终是神所安排的。但就像他安排耶稣和约伯进入到试探当中，绝不是出于恶意；同样，他让我们进入到这些试探当中，也是出于他良善的心。如果我们在试探当中跌倒，他会忧伤；如果我们在试探当中取胜，他会喜悦；当我们走过这些试探时，如果跌倒了但仍愿意回到他那里，他会接纳；如果取胜了，他会喜悦地看着我们享受他所赐下的丰厚奖赏。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而神就是这样把我们带入到一个又一个由魔鬼或者人所造成的“试探”当中来“试炼”我们。雅各书1:2节说：“我的弟兄们，你们落在百般试炼中，都要以为大喜乐， 因为知道，你们的信心经过试验就生忍耐。但忍耐也当成功，使你们成全、完备，毫无缺欠。”彼得前书1:6节也说，神让我们经历百般的试炼，是叫我们的信心能比那被火试验仍然能坏的金子更显宝贵，可以在耶稣基督显现的时候得着称赞、荣耀和尊贵。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以基督徒这一生，神为了让我们让我们成全、完备、毫无欠缺，为了在主再来的日子让我们得着称赞、荣耀和尊贵，会把我们带入到一个又一个试炼当中去，让我们能够在其中训练忍耐、并且不断得胜。这就是属灵争战，这个过程本质上，就是我们我们与魔鬼不断角力，并最终得胜的过程。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、认识试探的本质")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那怎么样才能得胜呢？下一次，我们会讲耶稣是如何得胜的。刚才我说了，耶稣被试探，是圣子这个位格在人性中被试探，或者说他是作为一个完全的人被试探，因此我们是可以效法他的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天呢，我们先一起来对试探做一些更深入的认识。既然我们的仇敌是魔鬼，我们就要认识他的手段。了解敌人，我们就可以更好地击败敌人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们先来看路加福音第4章第13节，这里说到“魔鬼用完了各样的试探”。也就是说在这四十天左右的试探中，魔鬼用尽了各样的办法来试探耶稣，但都没能让他跌倒。但圣经当中只记载了最后的三个试探，我想可能有这么两个原因：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一是这最后的三个试探是这四十天以来最强烈的。这个比较好理解，从魔鬼这边来看，最后关头了，魔鬼一定是使出浑身解数来使耶稣失败。从耶稣这边来看，当时间满了，神撤走对耶稣能量的供应，耶稣会体会到禁食四十天而有的身体的极度虚弱，这种虚弱显然也必然会影响他的精神状态，即使他精神上不一定也是同样衰弱的，但至少会受影响，这个我想我们只要经历过禁食，或者哪怕有过饿肚子经历的人，都会有所体会。这也与我们所说的，耶稣是作为人来受试探，是相吻合的。神所创造的人，肉体和精神之间是互相影响的。所以耶稣40天没有吃东西，他的身体处于极度虚弱的状态，因此魔鬼这时候的试探对他而言是极大考验。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二个原因，我想可能是因为这三个试探具有代表性。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们首先来看一下什么会构成一个魔鬼对我们的“试探”。在第一个试探中，第3节，魔鬼说“你若是神的儿子，可以吩咐这块石头变成食物！”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来想一想，如果是你在那个时候，40天没有吃东西，身体极度饥饿。那么你是不是想要吃东西呢？当然是的。但如果这个时候有人过来给你说“你若是神的儿子，可以吩咐这块石头变成食物！”你会怎么反应呢？如果是我，我会无奈地说：“兄弟，我也想让这石头变成红烧肉，但臣妾真的做不到啊！”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到没有，魔鬼这个对耶稣的试探，实际上对我不会构成一个真实的试探。虽然我确实需要食物，但他所提供的这种获得食物的方法，我知道自己没有能力来做。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而这对耶稣则不然。他同样想吃东西，但他有没有能力来做呢？我们刚才说过，所谓道成肉身，是指圣子这个位格在神性上添加了人性，而在世期间他是抑制了自己神性的发挥，作为人活在这个世上。但是他的神性不是没有了，而是仍然在圣子这个位格中，只不过是圣子主动压抑住了他的神性。因此，耶稣作为圣子，虽然在人性中他自己和我一样都不能使石头变成食物，但他却可以不再抑制自己的神性，因此他可以来做这件事，并且一定会成功。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们因此可以看到，魔鬼对人的试探之所以构成一个试探，要同时具备三个方面的要素：（1）被试探的人确实有这个需求，或者说想要某个东西，并且（2）他也确实有可能来做某个行为，并且（3）他做了之后，是可能确实会成功地获得这个东西的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("下面两个试探也是同样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第5~6节：5魔鬼又领他上了高山，霎时间把天下的万国都指给他看， 6 对他说：“这一切权柄、荣华我都要给你，因为这原是交付我的，我愿意给谁就给谁。 7 你若在我面前下拜，这都要归你。” ")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第6节这里的“原是交付我的”，原文中是一个完成时态，表示这些权柄和荣华已经给他了，而不是“原本是打算交付我，但实际上还没交付”的意思。魔鬼在这里是用对万国的权柄来试探耶稣。同样的，我们一起来看看，（1）耶稣是否想要这个？（2）他是不是能做这件事？（3）而他做了是否有可能成功得到想要的这个东西？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果耶稣并不想要这些权柄，那么魔鬼这个试探就对他不构成一个真实的试探。我举个例子，如果一个在读大学的弟兄，你的老师对你说，你如果继续信耶稣，我就不允许你以后去扫大街。这对你来说这就不会构成一个试探，因为你本来也不想去扫大街，对不对？但是如果他说，你如果继续信耶稣，我就让你拿不到学位，这对你就构成一个真实的试探，因为你真的想毕业。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么耶稣是不是想要对这个世界的权柄呢？当然了，因为这就是他来到这里的目的，这也正是父差派他来到这个世界的目的之一。歌罗西书1：16说万有都是为他造的；在路加福音21:33~41节有一个凶恶园户的比喻，耶稣也表明他知道自己是来承受产业的。天父的意思是要把这个世界给他的儿子，他的儿子当然就是顺着天父的意思去想。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么耶稣是不是能做“对魔鬼下拜”这件事呢？当然他能够做到，任何人都能做到，这个比较好理解。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那他做了是否有可能真的成功得到这些权柄和荣华呢？注意耶稣在这个试探中对魔鬼的回答。他并没有说你骗人，你其实根本就没有这些东西。如果是这样，那么这就不构成一个真实的试探。我还是举刚才的例子。比如你的老师告诉你说，你如果否认耶稣，我就给你个诺贝尔奖。这对你不会是试探，因为虽然你确实想得诺贝尔奖，也确实有这个能力做出否认耶稣的事情，但你这样做了，他也绝不可能给你诺贝尔奖。但是你老师告诉你，你如果否认耶稣，我就不会把你开除出学校，这对你会是个试探，因为他真有可能做得到。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣是承认了，从某种意义上说，魔鬼确实是有这万国的权柄和荣耀的。这一点并不奇怪，魔鬼确实是这个世界的空中掌权者（以弗所书2:2对此有确认），他也确实可能把他所掌管的这个世界交给拿撒勒人耶稣来掌管。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣想要对万国的权柄，他能够去做到去向魔鬼下拜，这样做了之后，他也确实可能得到他想要的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们再来看第三个试探同样如此。第9~10节，“魔鬼又领他到耶路撒冷去，叫他站在殿顶上，对他说：“你若是神的儿子，可以从这里跳下去！  因为经上记着说：‘主要为你吩咐他的使者保护你，他们要用手托着你，免得你的脚碰在石头上。’”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里耶稣也是能够做到从殿顶上跳下去的。那在这样的试探中，魔鬼是用什么耶稣想要的来试探他呢？这个试探和第一个试探，最开始都是用“你若是神的儿子”来开始的。但第一个试探中，魔鬼是让他自己动用自己的能力，也就是说，动用他的神性来使石头变成食物；而这里，魔鬼是让他去动用天父的能力来保护他，并且在这里引用了诗篇第91篇的经文。在这篇诗篇里面，神承诺他爱那专心爱他的人，他会搭救、保护他们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么魔鬼在这里的潜台词就是，你从这里跳下去，就可以知道你真是神的儿子、神真爱着你，因为他必然会搭救、保护你，就像他所承诺的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那耶稣是否想要确认天父爱呢？当然，作为一个爱神的人，他时时刻刻都需要确认天父是爱他的。因为作为一个人，一个关系性的受造物，别人对我们的爱，一方面让我们可以确认自己的身份、另一方面也为我们自己的心灵提供安全感。比如在一个家庭关系当中，爸爸妈妈不断通过言语、行为向一个孩子确认自己爱他，这个孩子就会确定自己是是属于这个家的；在一个教会或者一个团契关系中同样，弟兄姐妹们不断通过言语、行为向某个弟兄或姐妹确认自己爱他，他就会确定自己是属于这个教会、这个团契的。在这种归属感中你就可以定义自己的身份：我是这个家庭的一员，我是这个教会的一员，我是这个团契的一员；并且你也会在这样的关系中感到安全。不仅在这里感到安全，当面对这些关系之外的人或者事的时候，因为你知道自己是有退路的，所以你也会更放松，或者说更勇敢。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们要在与人的关系中确认对方爱我们是如此重要，何况在我们与神的关系中了。我们这些悖逆的儿女都能认识到不断确认神对我们的爱是何等重要，何况那充满智慧的耶稣了。而且我想，现在耶稣自己知道自己落入到试探当中，也自己知道他是顺服天父的旨意而落入到试探当中，因此在此时此刻，他更需要确认天父是爱他的。大家可以去回想一下自己的信仰经历。很多人进入患难、试探中时，会开始怀疑神是否还爱我。虽然我们下次讲道中，会看到耶稣并没有产生这样的怀疑，但我们的这种心态，这不正说明一个正常的人在这种时候，是需要确认神是爱你的吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣当然是想要确认天父的爱，就像他想要获得食物，想要获得对万国的权柄。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而他有能力跳下去，并且信实的神既然承诺过会派使者托住他，那么他跳下去当然就会被神保护，看到神确实爱他；所以他有能力做，做了也确实会成功。同样，他有能力动用他的神性，而如果他动用了，确实会使石头变成食物，所以他有能力做，做了也确实会成功；他拜魔鬼就可以获得对受造界的权柄，他有能力做到这一点，而他做了，魔鬼至少是可能真会实现它的许诺，他有能力做，做了也确实可能成功。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，魔鬼对他的这三个试探，对他而言是真实的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到了吗？这就是魔鬼试探的手段。他向你展示一个你真实需要的东西，然后再向你提供一个你自己确实有能力实施的行为，并且让你看到实施这个行为以满足这需要的可能性，引诱你来实施它。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家可以分析一下自己所经历过的试探是不是这样的。有时候不一定一眼能看出来，但如果你安静下来，在祷告中去查究，你会看到这样一种模式。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好，刚才我们说为什么圣经记载这三个试探，除了强度最猛烈，还因为这三个试探具有典型性，我们已经介绍了所有试探基本内容。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("另外我想这三个试探之所以典型，也许是它们代表了人最重要的三个需要。从刚才我们的讲解中，大家可能已经可以看出来，这三个需要就是：物质肉身产生的需要、生命目产生的需要，以及出于位格关系产生的需要。我稍微来解释一下：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第一个，物质肉身产生的需要。因为神创造的人是一个有灵魂，有肉体的存在，所以这个物质的肉身本身就会产生需要。肉体会饿，会渴，会有性欲，会有疼痛等等这些，都会产生我们的需要。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而生命目的产生的需要来自于我们是有灵魂的人。因此人不仅是做事、活着，而总会面对为什么我要做这件事，为什么我要活着，我做某件事情的意义是什么，我的生命的意义是什么等等这些问题，对这些问题需要答案；并且一旦有了答案，就需要找方法来实现它们。耶稣也是一样，他很清楚自己的人生的目的是什么，但也需要来实现这个目的。所以我们的灵魂，或者说生命目的会产生这些需求。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("位格关系产生的需要，是指我们人被创造成一个有位格的生命体，因此我们需要被爱，需要获得身份认同、需要获得安全感，需要获得勇气，而这些是在我们与其他有位格的生命体发生关系中发生的，这些我们可以说都是位格关系产生的需要。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们每个人具体在某一个场景下的需要不同，但是我想至少绝大部分可以划分到这三个类别当中。而魔鬼就会利用这些需要来试探我们，他希望我们以犯罪的方式来满足这些需要，希望我们因此与神的关系被破坏，进而他不仅可以嘲笑我们，也可以嘲笑神。其实魔鬼使知道自己的结局的，我们犯罪、我们与神的关系被破坏，其实对他本身而言没有任何好处，但他就是乐在其中，所以说他是变态，是魔鬼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但是兄弟姐妹们，魔鬼只是使用这些需要来试探我们，决定还是由我们自己做。需要和犯罪之间，并不是必然的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看雅各书1：14~15节说：“但各人被试探，乃是被自己的私欲牵引、诱惑的。 私欲既怀了胎，就生出罪来；罪既长成，就生出死来。”")]),t._v(" "),v("font",{attrs:{size:"5"}},[t._v("大家看这里描述的这个过程，先是有私欲，然后私欲才会导致我们犯罪。所以我们虽然有需求，但这个需求如果不形成私欲，我们不会犯罪；而虽然有了私欲，但是我们及时把它杀死，我们也不会犯罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("什么是私欲呢？脱离了神来满足自己需求的欲望，就是私欲。所以魔鬼所做的，就是去挑动人的私欲。他首先把你的需求展示给你（有些需求甚至是你自己都还没有意识到的），然后把脱离了神来满足这个需求的手段告诉你，并且让你看到用这个手段确实有可能实现需求，这样来引动你的私欲。这就是试探的本质。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当试探到来时，需求是你当时真实具有的，你改变不了；手段和实现需求之间的可能性也是客观在那儿的，你决定不了；你能决定的，就是是否去动用魔鬼告诉你的这个满足需求的手段。这正是耶稣拒绝试探所用的方法。我们下一次会来详细讲。今天我们要学习到的，是认识试探的目的以及认识试探的本质。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("试探的本质，就是引动你的私欲，也就是让你用违背神旨意的方法来满足你的需要。我建议大家有意识地每天或者定期，静下心来，做个祷告，求神给你亮光，然后你去复盘自己这一天或者这段时间遇到过的试探，尤其是那些犯罪、跌倒的情况。你想一想，当时你的哪个需求被触碰到了？你用了什么手段以期来实现这个需求？最开始查清自己的这些心思意念可能会比较困难，但是当我们对这种查验越来越熟练，我们就会越来越对自己内心的需求敏感，也会越来越对试探敏感。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而魔鬼之所以会试探我们，是因为他喜欢看到我们失败，享受我们犯罪。但不要忘了，魔鬼没有最终的决定权。我们是否被魔鬼试探、什么时候被魔鬼试探、魔鬼能怎么试探我们、魔鬼的试探有多强烈，这一切说到底，都是神在安排的。而神是把我们放入到“试探”当中来“试炼”我们，他不是喜悦、享受我们失败、犯罪，他是喜悦、享受我们忍耐、成功，因为这说明我们更加成全、完备、圣洁，有谁的父母不愿意看到自己的孩子越来越好呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，我们在主祷文中求神不要让我们遇见试探，这是一种谦卑和谨慎，因为谁也不能肯定自己在某个试探下会不会跌倒，包括耶稣自己（这一点我们下一次会来讲）；但如果神引导我们进入到试探当中，我们也不要害怕，神既然如此安排，他必有他的美意，他也必在其中保守他的羊群，就像诗篇23所说：我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在。即使我们在其中跌倒了，也不怕遭害，因为在我们的主耶稣基督里，没有什么能叫我们与神的爱隔绝，神仍然接纳我们、搀扶我们、医治我们、也坚固我们。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);